package com.prima.factory.controller;
import java.time.*; import java.util.*; import jakarta.servlet.http.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import com.prima.factory.dto.ApiResponse; import com.prima.factory.mapper.UserMapper;
@RestController @RequestMapping("/api/v1/auth") public class AuthController { private final UserMapper users; private final PasswordEncoder encoder; public AuthController(UserMapper u,PasswordEncoder e){users=u;encoder=e;}
 @PostMapping("/login") ApiResponse<?> login(@RequestBody Map<String,String>b,HttpSession session){var u=users.find(b.get("username")); if(u==null||!encoder.matches(b.getOrDefault("password",""),String.valueOf(u.get("passwordHash")))) throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"아이디 또는 비밀번호가 올바르지 않습니다."); if(!"APPROVED".equals(u.get("approvalStatus"))||Boolean.TRUE.equals(u.get("isLocked")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"승인되지 않았거나 잠긴 계정입니다."); session.setAttribute("USER_ID",u.get("id")); return ApiResponse.ok(Map.of("id",u.get("id"),"username",u.get("username"),"name",u.get("fullName")));}
 @PostMapping("/logout") ApiResponse<?> logout(HttpSession s){s.invalidate();return ApiResponse.ok(Map.of());} @GetMapping("/me") ApiResponse<?> me(HttpSession s){if(s.getAttribute("USER_ID")==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED);return ApiResponse.ok(Map.of("id",s.getAttribute("USER_ID")));}
 @PostMapping("/signup") ApiResponse<?> signup(@RequestBody Map<String,Object>b){var copy=new HashMap<>(b);copy.put("passwordHash",encoder.encode(String.valueOf(b.get("password"))));users.signup(copy);return ApiResponse.ok(Map.of("status","PENDING"));}
}
